#!/usr/bin/env node
// Bundles packages/core/src/knowledge/*.md into packages/core/src/knowledge/bundle.ts (plan 28 §3a), so the browser
// gets the playbook as string constants with no fetch and no markdown runtime. Run after editing a .md file:
//
//   node scripts/knowledge-bundle.mjs            # write bundle.ts
//   node scripts/knowledge-bundle.mjs --check    # exit 1 when bundle.ts is stale (the core test does the same)
//
// The first "# Title" line becomes the section title; the "Sources: ..." paragraph is kept out of the model's copy
// (it is for the people editing the files) and the rest is the body, verbatim.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const dir = join(here, '..', 'packages', 'core', 'src', 'knowledge');
const out = join(dir, 'bundle.ts');

export function parseKnowledge(id, md) {
  const lines = md.replace(/\r\n/g, '\n').split('\n');
  const titleLine = lines.find((l) => l.startsWith('# '));
  if (!titleLine) throw new Error(`${id}.md has no "# Title" line`);
  const title = titleLine.slice(2).trim();
  const body = lines
    .filter((l) => l !== titleLine && !/^Sources:/.test(l))
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  return { id, title, body };
}

export function renderBundle(sections) {
  const rows = sections
    .map(
      (s) =>
        `  ${JSON.stringify(s.id)}: {\n    title: ${JSON.stringify(s.title)},\n    body: ${JSON.stringify(s.body)},\n  },`,
    )
    .join('\n');
  return [
    '// Generated by scripts/knowledge-bundle.mjs from the .md files in this folder. Do not edit; edit the .md and rerun.',
    '/** One playbook section: the title from the file and its prose, sources line removed. */',
    'export interface KnowledgeFile {',
    '  title: string;',
    '  body: string;',
    '}',
    '',
    'export const KNOWLEDGE_FILES: Record<string, KnowledgeFile> = {',
    rows,
    '};',
    '',
  ].join('\n');
}

export function buildBundle() {
  const files = readdirSync(dir)
    .filter((f) => f.endsWith('.md'))
    .sort();
  const sections = files.map((f) => parseKnowledge(f.replace(/\.md$/, ''), readFileSync(join(dir, f), 'utf8')));
  return renderBundle(sections);
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const text = buildBundle();
  if (process.argv.includes('--check')) {
    let current = '';
    try {
      current = readFileSync(out, 'utf8');
    } catch {
      current = '';
    }
    if (current !== text) {
      console.error('knowledge/bundle.ts is stale: run node scripts/knowledge-bundle.mjs');
      process.exit(1);
    }
    console.log('knowledge/bundle.ts is current');
  } else {
    writeFileSync(out, text);
    console.log(`wrote ${out}`);
  }
}
